/** One line per item plus a Total line, joined with newlines (see SPEC.md). */
export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	let total = 0;
	const out: string[] = [];
	for (const line of lines) {
		total += line.cents;
		out.push(`${line.label}: ${formatCents(line.cents)}`);
	}
	out.push(`Total: ${formatCents(total)}`);
	return out.join('\n');
}

